Method.Implementation:
	$$$TRACE("Inside Select getMaxMsprInfoSeqNum Method")
	set maxSegNum=0
	set pRes = ##class(EnsLib.SQL.Snapshot).%New()
	set pRes.MaxRowsToGet = -1
	set tSQL = "SELECT max(TRANSACTION_SEQ_NUM) FROM ISSALDAP.mspr_info"
	//set tSQL = "SELECT max(TRANSACTION_SEQ_NUM) FROM ISSALDAP.MSPR_PROVIDER_AFFILIATION"

 	set tSC = ..Adapter.ExecuteQueryParmArray(.pRes,tSQL)
 	set maxSeqNum=""

	if tSC = 1
	{
		$$$TRACE("Successfully executed Query:"_tSQL)
		If ($ISOBJECT(pRes)&&(pRes.RowCount>0)){
			$$$TRACE("Retrieve max seg num from the Response")
			set rowNum=pRes.Next(.sc)
			$$$TRACE("Error Status"_sc)
			if ($$$ISERR(sc)){
				$$$TRACE("Error Reading result set")
				set tSC=$$$ERROR("Error Reading Result set")
			}else{
				set maxSeqNum=pRes.Get("max(TRANSACTION_SEQ_NUM)")
				$$$TRACE("rowNum "_rowNum_" TRANSACTION_SEQ_NUM "_maxSeqNum)
			}
		}

	}
	else
	{
		$$$TRACE("Failed to execute Query:"_tSQL)	
	}

	Quit maxSeqNum


	$$$TRACE("Inside addMsprData Method")
	d ..Adapter.SetAutoCommit(0)

	#dim tSC As %Status=$$$OK

	try{
     set sourceSystem=pRequest.SourceSystem
     $$$TRACE("SOURCE SYS:"_sourceSystem)

      if (sourceSystem="CO") || (sourceSystem="CA") {
	    $$$TRACE("CA or CO insert...")	
        set tSC= ..insertCactusOrCorpprvToLdapTables(pRequest)
      }
      elseif (sourceSystem="OR") || (sourceSystem="WD"){
	    $$$TRACE("HR insert...")
        set tSC=..insertOracleHrToLdapTables(pRequest)
      }
      elseif ((sourceSystem="OX") || (sourceSystem="SF")){
	    $$$TRACE("OAX/SF insert...")
        set tSC=..insertOaxToLdapTables(pRequest)
      }
      else {
	    $$$TRACE("Source System: "_sourceSystem_" is not found...")
      }

	} 
	Catch eException {
       $$$TRACE("Inside Catch111")
 	   set errTxt = $System.Status.GetErrorText(%objlasterror)
	   Set repNcid = errTxt
       $$$LOGERROR("Exception in insert data to ldap Oracle tables: " _errTxt _ ", Excp:" _ eException.Name _ " " _ eException.Code _ " " _ eException.Location)
       $$$LOGERROR($ZERROR)
	}

	If $$$ISOK(tSC){
		d ..Adapter.Commit()  
	}Else{
		d ..Adapter.Rollback() 
	}	

	Quit tSC

      $$$TRACE("Inside insertOracleHrToLdapTables method")
      set retryCnt=0
      do {
	       set tSc=..addHrMsprInfo(pRequest.ldapTableValues.MSPRINFO)  
	       $$$TRACE("SQL Gateway status: "_tSc)
	       if tSc < 1 {
		      set retryCnt = retryCnt+1
		      $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	          hang ..RetryInterval
	       }
       } while (tSc < 1) && (retryCnt<5)
       if tSc < 0 {
	      quit $$$ERROR(563,"Insert into MSPR_INFO table failed. ")
       }
       else {
         $$$TRACE("After Setting value... ")
         set affobj= pRequest.ldapTableValues.MSPRAFFLIATION
         if affobj'="" {
          //set the parameter for affliation table
           set retryCnt=0
           do {
	          set tSc=..addHrMsprAffiliationValues(affobj)
	          if tSc < 1 {
		         set retryCnt = retryCnt+1
		         $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	             hang ..RetryInterval
	          }
           } while (tSc < 1) && (retryCnt<5)
          $$$TRACE("After Insert close 2")
         }
       }
      quit tSc

      $$$TRACE("Inside insertOaxToLdapTables method")
      set retryCnt=0
      do {
	       set tSc=..addOaxMsprInfo(pRequest.ldapTableValues.MSPRINFO)  
	       $$$TRACE("SQL Gateway status: "_tSc)
	       if tSc < 1 {
		      set retryCnt = retryCnt+1
		      $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	          hang ..RetryInterval
	       }
       } while (tSc < 1) && (retryCnt<5)
       if tSc < 1 {
	      quit $$$ERROR(563,"Insert into MSPR_INFO table failed. ")
       }
       else {
         $$$TRACE("After Setting value... ")
         set affobj= pRequest.ldapTableValues.MSPRAFFLIATION
         if affobj'="" {
          //set the parameter for affliation table
           set retryCnt=0
           do {
	          set tSc=..addOaxMsprAffiliationValues(affobj)
	          if tSc < 1 {
		         set retryCnt = retryCnt+1
		         $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	             hang ..RetryInterval
	          }
           } while (tSc < 1) && (retryCnt<5)
          $$$TRACE("After Insert close 2")
         }
       }
      quit tSc

      $$$TRACE("Inside insertCactusOrCorpprvToLdapTable method")
      set retryCnt=0
      do {
	       set tSc=..addMsprInfo(pRequest.ldapTableValues.MSPRINFO)  
	       $$$TRACE("SQL Gateway status: "_tSc)
	       if tSc < 1 {
		      set retryCnt = retryCnt+1
		      $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	          hang ..RetryInterval
	       }
       } while (tSc < 1) && (retryCnt<5)
       if tSc < 1 {
	      quit $$$ERROR(563,"Insert into MSPR_INFO table failed. ")
       }
       else {
	     $$$TRACE("After Setting value... ")
         set affiliationList= pRequest.ldapTableValues.MsprAffliationList
         $$$TRACE("MsprAffliation List count:"_affiliationList.Count())
         FOR i=1:1:affiliationList.Count(){
	       $$$TRACE("Inside affiation Loop-"_i)
	       set affobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRPRAFFLIATION).%New()
           set affobj = affiliationList.GetAt(i) 	                         
          //set the parameter for affliation table
           set retryCnt=0
           do {
	          set tSc=..addMsprAffiliationValues(affobj)
	          if tSc < 1 {
		         set retryCnt = retryCnt+1
		         $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	             hang ..RetryInterval
	          }
           } while (tSc < 1) && (retryCnt<5)
           $$$TRACE("After Insert close 2")
         }
         set specialTyList= pRequest.ldapTableValues.MsprSpecialtyList
         $$$TRACE("specialTyList count:"_specialTyList.Count())
         FOR i=1:1:specialTyList.Count(){
	       $$$TRACE("Inside Specialty Loop-"_i)
	       set specialTyobj = ##class(IHC.ITF.ITFCOMMON.Request.MSPRSPECIALTY).%New()
           set specialTyobj = specialTyList.GetAt(i) 	                         
          //set the parameter for Specialty table
           set retryCnt=0
           do {
	           set tSc = ..addMsprSpecialtyValues(specialTyobj)
	          if tSc < 1 {
		         set retryCnt = retryCnt+1
		         $$$TRACE("Hang one sencod before re-try..., "_retryCnt_" interval: "_..RetryInterval)
	             hang ..RetryInterval
	          }
           } while (tSc < 1) && (retryCnt<5)

           $$$TRACE("After insert Specialty close 3")
         }
       }

      quit tSc
